/**
 * OpenAPI spec → HTTPRoute parsing.
 *
 * Port of Python FastMCP's `fastmcp.utilities.openapi.parser`, operating on
 * the plain spec object instead of validated pydantic models (the TypeScript
 * side does not validate the spec; malformed pieces are skipped with a
 * warning where Python's per-item error handling does the same). Reference
 * resolution is local-only: an external `$ref` in a request body, response,
 * or component walk throws; one in a parameter skips that parameter, exactly
 * like Python's per-scope error handling.
 */

import { parse as parseYaml } from 'yaml'
import type {
  HTTPRoute,
  HttpMethod,
  JsonSchema,
  ParameterInfo,
  ParameterLocation,
  RequestBodyInfo,
  ResponseInfo,
} from './types'
import { isPlainObject, truthy, warn } from './internal'
import { combineSchemasAndMapParams, discriminatorTargetName, isExternalRefError, replaceRefWithDefs } from './schemas'

/**
 * Load an OpenAPI spec from an object or from YAML/JSON text. YAML 1.2 is a
 * superset of JSON, so JSON text parses through the same path.
 */
export function loadSpec(spec: Record<string, unknown> | string): Record<string, unknown> {
  if (typeof spec !== 'string') return spec
  const parsed: unknown = parseYaml(spec)
  if (!isPlainObject(parsed)) {
    throw new Error('OpenAPI spec text must parse to an object')
  }
  return parsed
}

const HTTP_METHODS_LOWER = [
  'get',
  'put',
  'post',
  'delete',
  'options',
  'head',
  'patch',
  'trace',
] as const

const PRIMARY_SUCCESS_PRIORITY = ['200', '201', '202', '204', '207'] as const

const PARAMETER_LOCATIONS: readonly ParameterLocation[] = ['path', 'query', 'header', 'cookie']

function isSuccessStatusCode(statusCode: string): boolean {
  if (/^\s*[+-]?\d+\s*$/.test(statusCode)) {
    const code = parseInt(statusCode, 10)
    return code >= 200 && code < 300
  }
  return ['default', '2xx'].includes(statusCode.toLowerCase())
}

/** Parse an OpenAPI 3.x spec object into a list of HTTPRoute objects. */
export function parseOpenAPIToHttpRoutes(spec: Record<string, unknown>): HTTPRoute[] {
  const openapiVersion = typeof spec.openapi === 'string' ? spec.openapi : ''
  return new SpecParser(spec, openapiVersion).parse()
}

class SpecParser {
  constructor(
    private readonly spec: Record<string, unknown>,
    private readonly openapiVersion: string,
  ) {}

  private toParameterLocation(paramIn: string): ParameterLocation {
    if ((PARAMETER_LOCATIONS as readonly string[]).includes(paramIn)) {
      return paramIn as ParameterLocation
    }
    warn(`Unknown parameter location: ${paramIn}, defaulting to 'query'`)
    return 'query'
  }

  /** Resolve a `{$ref}` object to its target within the spec (local only). */
  private resolveRef(item: unknown): unknown {
    if (!isPlainObject(item) || typeof item.$ref !== 'string') return item
    const ref = item.$ref
    try {
      if (!ref.startsWith('#/')) {
        throw new Error(`External or non-local reference not supported: ${ref}`)
      }
      const parts = ref.replace(/^[#/]+/, '').replace(/[#/]+$/, '').split('/')
      let target: unknown = this.spec
      for (const part of parts) {
        if (/^\d+$/.test(part) && Array.isArray(target)) {
          target = target[Number(part)]
        } else if (isPlainObject(target)) {
          target = target[part]
        } else {
          throw new Error(`Cannot traverse part '${part}' in reference '${ref}'`)
        }
        if (target === null || target === undefined) {
          throw new Error(`Reference part '${part}' not found in path '${ref}'`)
        }
      }
      if (isPlainObject(target) && typeof target.$ref === 'string') {
        return this.resolveRef(target)
      }
      return target
    } catch (error) {
      throw new Error(`Failed to resolve reference '${ref}': ${(error as Error).message}`)
    }
  }

  /** Resolve a schema (or ref to one) and return it as a ref-converted copy. */
  private extractSchemaAsDict(schemaObj: unknown): JsonSchema {
    try {
      const resolved = this.resolveRef(schemaObj)
      let result: JsonSchema
      if (isPlainObject(resolved)) {
        // Deep copy: downstream steps mutate schemas in place, and the same
        // spec object may be parsed more than once.
        result = structuredClone(resolved)
      } else {
        warn(`Expected a schema object after resolving, got ${typeof resolved}. Using empty schema.`)
        result = {}
      }
      return replaceRefWithDefs(result)
    } catch (error) {
      if (isExternalRefError(error)) throw error
      warn(`Failed to extract schema: ${(error as Error).message}`)
      return {}
    }
  }

  private extractParameters(operationParams: unknown, pathItemParams: unknown): ParameterInfo[] {
    const extracted: ParameterInfo[] = []
    const seen = new Set<string>()
    const all = [
      ...(Array.isArray(operationParams) ? operationParams : []),
      ...(Array.isArray(pathItemParams) ? pathItemParams : []),
    ]

    for (const paramOrRef of all) {
      try {
        const parameter = this.resolveRef(paramOrRef)
        if (
          !isPlainObject(parameter) ||
          typeof parameter.name !== 'string' ||
          typeof parameter.in !== 'string'
        ) {
          warn(`Expected a parameter object after resolving. Skipping.`)
          continue
        }

        const location = this.toParameterLocation(parameter.in)

        // Skip duplicate parameters (same name and location).
        const key = `${parameter.name}�${parameter.in}`
        if (seen.has(key)) continue
        seen.add(key)

        let paramSchema: JsonSchema = {}
        if (truthy(parameter.schema)) {
          paramSchema = this.extractSchemaAsDict(parameter.schema)
        } else if (isPlainObject(parameter.content) && truthy(parameter.content)) {
          // Content-based parameter: use the first media type's schema.
          const firstMediaType = Object.values(parameter.content)[0]
          if (isPlainObject(firstMediaType) && truthy(firstMediaType.schema)) {
            paramSchema = this.extractSchemaAsDict(firstMediaType.schema)
          }
        }

        extracted.push({
          name: parameter.name,
          location,
          required: Boolean(parameter.required),
          schema: paramSchema,
          ...(typeof parameter.description === 'string'
            ? { description: parameter.description }
            : {}),
          ...(typeof parameter.explode === 'boolean' ? { explode: parameter.explode } : {}),
          ...(typeof parameter.style === 'string' ? { style: parameter.style } : {}),
        })
      } catch (error) {
        // Per-parameter failures (including external refs) skip the parameter.
        warn(`Failed to extract parameter: ${(error as Error).message}`)
      }
    }

    return extracted
  }

  private extractRequestBody(requestBodyOrRef: unknown): RequestBodyInfo | undefined {
    if (!truthy(requestBodyOrRef)) return undefined

    try {
      const requestBody = this.resolveRef(requestBodyOrRef)
      if (!isPlainObject(requestBody)) {
        warn(`Expected a request body object after resolving. Skipping request body.`)
        return undefined
      }

      const info: RequestBodyInfo = {
        required: Boolean(requestBody.required),
        contentSchema: {},
        ...(typeof requestBody.description === 'string'
          ? { description: requestBody.description }
          : {}),
      }

      if (isPlainObject(requestBody.content)) {
        for (const [mediaType, mediaTypeObj] of Object.entries(requestBody.content)) {
          if (isPlainObject(mediaTypeObj) && truthy(mediaTypeObj.schema)) {
            try {
              info.contentSchema[mediaType] = this.extractSchemaAsDict(mediaTypeObj.schema)
            } catch (error) {
              if (isExternalRefError(error)) throw error
              warn(`Failed to extract schema for media type '${mediaType}': ${(error as Error).message}`)
            }
          }
        }
      }

      return info
    } catch (error) {
      if (isExternalRefError(error)) throw error
      warn(`Failed to extract request body: ${(error as Error).message}`)
      return undefined
    }
  }

  private getPrimarySuccessResponse(
    operationResponses: Record<string, unknown>,
  ): [string, unknown] | null {
    for (const code of PRIMARY_SUCCESS_PRIORITY) {
      if (code in operationResponses) return [code, operationResponses[code]]
    }
    for (const [statusCode, respOrRef] of Object.entries(operationResponses)) {
      if (isSuccessStatusCode(statusCode)) return [statusCode, respOrRef]
    }
    return null
  }

  /** Extract only the primary success response for the MCP component. */
  private extractResponses(operationResponses: unknown): Record<string, ResponseInfo> {
    const extracted: Record<string, ResponseInfo> = {}
    if (!isPlainObject(operationResponses) || !truthy(operationResponses)) return extracted

    const primary = this.getPrimarySuccessResponse(operationResponses)
    if (primary === null) return extracted

    const [statusCode, respOrRef] = primary
    try {
      const response = this.resolveRef(respOrRef)
      if (!isPlainObject(response)) {
        warn(`Expected a response object after resolving for status code ${statusCode}. Skipping.`)
        return extracted
      }

      const respInfo: ResponseInfo = {
        contentSchema: {},
        ...(typeof response.description === 'string' ? { description: response.description } : {}),
      }

      if (isPlainObject(response.content)) {
        for (const [mediaType, mediaTypeObj] of Object.entries(response.content)) {
          if (isPlainObject(mediaTypeObj) && truthy(mediaTypeObj.schema)) {
            try {
              // Track whether this was a top-level component ref before resolution.
              let topLevelSchemaName: string | null = null
              const mediaSchema = mediaTypeObj.schema
              if (isPlainObject(mediaSchema) && typeof mediaSchema.$ref === 'string') {
                if (mediaSchema.$ref.startsWith('#/components/schemas/')) {
                  topLevelSchemaName = mediaSchema.$ref.split('/').pop() as string
                }
              }

              const schemaDict = this.extractSchemaAsDict(mediaSchema)
              if (topLevelSchemaName !== null) {
                schemaDict['x-fastmcp-top-level-schema'] = topLevelSchemaName
              }
              respInfo.contentSchema[mediaType] = schemaDict
            } catch (error) {
              if (isExternalRefError(error)) throw error
              warn(
                `Failed to extract schema for media type '${mediaType}' in response ${statusCode}: ${(error as Error).message}`,
              )
            }
          } else {
            // Record the media type even without a schema so MIME type
            // inference can still use the declared content type.
            respInfo.contentSchema[mediaType] ??= {}
          }
        }
      }

      extracted[statusCode] = respInfo
    } catch (error) {
      if (isExternalRefError(error)) throw error
      warn(`Failed to extract response for status code ${statusCode}: ${(error as Error).message}`)
    }

    return extracted
  }

  /** Collect schema names referenced by `schema`, transitively. */
  private extractSchemaDependencies(
    schema: unknown,
    allSchemas: Record<string, JsonSchema>,
    collected: Set<string> = new Set(),
    followDiscriminator = false,
  ): Set<string> {
    const collect = (schemaName: string): void => {
      if (!collected.has(schemaName) && schemaName in allSchemas) {
        collected.add(schemaName)
        findRefs(allSchemas[schemaName])
      }
    }

    const findRefs = (obj: unknown): void => {
      if (isPlainObject(obj)) {
        if (typeof obj.$ref === 'string') {
          const ref = obj.$ref
          if (ref.startsWith('#/$defs/') || ref.startsWith('#/components/schemas/')) {
            collect(ref.split('/').pop() as string)
          }
        }

        if (followDiscriminator) {
          const discriminator = obj.discriminator
          if (isPlainObject(discriminator) && isPlainObject(discriminator.mapping)) {
            for (const target of Object.values(discriminator.mapping)) {
              if (typeof target !== 'string') continue
              const name = discriminatorTargetName(target)
              if (name !== null) collect(name)
            }
          }
        }

        for (const value of Object.values(obj)) findRefs(value)
      } else if (Array.isArray(obj)) {
        for (const item of obj) findRefs(item)
      }
    }

    findRefs(schema)
    return collected
  }

  private extractInputSchemaDependencies(
    parameters: ParameterInfo[],
    requestBody: RequestBodyInfo | undefined,
    allSchemas: Record<string, JsonSchema>,
  ): Record<string, JsonSchema> {
    const needed = new Set<string>()

    for (const param of parameters) {
      if (truthy(param.schema)) {
        this.extractSchemaDependencies(param.schema, allSchemas, needed)
      }
    }

    // Request bodies are flattened into a single object, so discriminated
    // subtypes need to come along.
    if (requestBody && truthy(requestBody.contentSchema)) {
      for (const contentSchema of Object.values(requestBody.contentSchema)) {
        this.extractSchemaDependencies(contentSchema, allSchemas, needed, true)
      }
    }

    return Object.fromEntries([...needed].filter((n) => n in allSchemas).map((n) => [n, allSchemas[n]]))
  }

  private extractOutputSchemaDependencies(
    responses: Record<string, ResponseInfo>,
    allSchemas: Record<string, JsonSchema>,
  ): Record<string, JsonSchema> {
    if (!truthy(responses) || !truthy(allSchemas)) return {}

    const needed = new Set<string>()

    for (const response of Object.values(responses)) {
      if (!truthy(response.contentSchema)) continue

      for (const contentSchema of Object.values(response.contentSchema)) {
        this.extractSchemaDependencies(contentSchema, allSchemas, needed)

        const schemaName = contentSchema['x-fastmcp-top-level-schema']
        if (typeof schemaName === 'string' && schemaName in allSchemas) {
          needed.add(schemaName)
          this.extractSchemaDependencies(allSchemas[schemaName], allSchemas, needed)
        }
      }
    }

    return Object.fromEntries([...needed].filter((n) => n in allSchemas).map((n) => [n, allSchemas[n]]))
  }

  parse(): HTTPRoute[] {
    const routes: HTTPRoute[] = []

    const paths = this.spec.paths
    if (!isPlainObject(paths) || !truthy(paths)) {
      warn('OpenAPI schema has no paths defined.')
      return []
    }

    // Extract component schema definitions (per-definition failures skip
    // that definition, external refs included — Python parity).
    const schemaDefinitions: Record<string, JsonSchema> = {}
    const components = this.spec.components
    if (isPlainObject(components) && isPlainObject(components.schemas)) {
      for (const [name, schema] of Object.entries(components.schemas)) {
        try {
          schemaDefinitions[name] = this.extractSchemaAsDict(this.resolveRef(schema))
        } catch (error) {
          warn(`Failed to extract schema definition '${name}': ${(error as Error).message}`)
        }
      }
    }
    for (const [name, schema] of Object.entries(schemaDefinitions)) {
      if (isPlainObject(schema)) {
        schemaDefinitions[name] = replaceRefWithDefs(schema)
      }
    }

    for (const [pathStr, pathItemObj] of Object.entries(paths)) {
      if (!isPlainObject(pathItemObj)) {
        warn(`Skipping invalid path item for path '${pathStr}'`)
        continue
      }

      const pathLevelParams = pathItemObj.parameters

      for (const methodLower of HTTP_METHODS_LOWER) {
        const operation = pathItemObj[methodLower]
        if (!isPlainObject(operation)) continue

        const method = methodLower.toUpperCase() as HttpMethod

        try {
          const parameters = this.extractParameters(operation.parameters, pathLevelParams)
          const requestBody = this.extractRequestBody(operation.requestBody)
          const responses = this.extractResponses(operation.responses)

          const extensions = Object.fromEntries(
            Object.entries(operation).filter(([key]) => key.startsWith('x-')),
          )

          const requestSchemas = this.extractInputSchemaDependencies(
            parameters,
            requestBody,
            schemaDefinitions,
          )
          const responseSchemas = this.extractOutputSchemaDependencies(
            responses,
            schemaDefinitions,
          )

          const route: HTTPRoute = {
            path: pathStr,
            method,
            ...(typeof operation.operationId === 'string'
              ? { operationId: operation.operationId }
              : {}),
            ...(typeof operation.summary === 'string' ? { summary: operation.summary } : {}),
            ...(typeof operation.description === 'string'
              ? { description: operation.description }
              : {}),
            tags: Array.isArray(operation.tags) ? [...(operation.tags as string[])] : [],
            parameters,
            ...(requestBody !== undefined ? { requestBody } : {}),
            responses,
            requestSchemas,
            responseSchemas,
            extensions,
            openapiVersion: this.openapiVersion,
            flatParamSchema: {},
            parameterMap: {},
          }

          // Pre-calculate the flat schema and parameter mapping.
          try {
            const [flatSchema, parameterMap] = combineSchemasAndMapParams(route)
            route.flatParamSchema = flatSchema
            route.parameterMap = parameterMap
          } catch (error) {
            warn(
              `Failed to pre-calculate schema for route ${method} ${pathStr}: ${(error as Error).message}`,
            )
            route.flatParamSchema = { type: 'object', properties: {} }
            route.parameterMap = {}
          }
          routes.push(route)
        } catch (error) {
          if (isExternalRefError(error)) throw error
          const opId =
            typeof operation.operationId === 'string' ? operation.operationId : 'unknown'
          warn(
            `Failed to process operation ${method} ${pathStr} (ID: ${opId}): ${(error as Error).message}`,
          )
        }
      }
    }

    return routes
  }
}
